scenarios.example_code:
import { canonicalize } from '@projexlight/sdk-geo';
const { address_id, was_existing } = await canonicalize({
  tenant_id, input: '123 Main, Suite 4, Cambridge MA 02139',
});

import { geocode } from '@projexlight/sdk-geo';
const { lat, lng, accuracy_m } = await geocode({
  address_id, force_refresh: false,
});

import { reverseGeocode } from '@projexlight/sdk-geo';
const { address_id, distance_m } = await reverseGeocode({
  lat: 42.3601, lng: -71.0589, max_distance_m: 50,
});

import { addAlias } from '@projexlight/sdk-geo';
await addAlias({
  address_id: mit_canonical_id, alias_input: 'Bldg 4, MIT',
  added_by_persona_id,
});

import { mergeAddresses } from '@projexlight/sdk-geo';
await mergeAddresses({
  from_address_id: dup_id, to_address_id: canonical_id,
  merged_by_persona_id, reason: 'apartment-vs-suite-normalization',
});
